mapper.sql:
SELECT '${taskSourceId}' AS source_id, LPAD(CAST(mes_pro_edhr_work_task.id AS CHAR),20,'0') AS row_order_key, CAST(mes_pro_edhr_work_task.id AS CHAR) AS business_id,
CONCAT('${taskSourceId}:', mes_pro_edhr_work_task.id) AS task_key, '${taskCategory}' AS task_type, '${taskSourceLabel}' AS source,
CONVERT(CONCAT(CASE mes_pro_edhr_work_task.task_type WHEN 'FILL' THEN '请填写批记录' WHEN 'REVIEW' THEN '请复核批记录' WHEN 'APPROVE' THEN '请批准批记录' WHEN 'REWORK' THEN '请修改退回的批记录' WHEN 'ARCHIVE' THEN '请完成批记录归档' WHEN 'CLOSE' THEN '请关闭批记录' WHEN 'RELEASE_APPROVE' THEN '请完成上市放行审批' WHEN 'PQC_PRODUCTION_RELEASE' THEN '请完成 PQC 生产放行' WHEN 'DEVIATION_RECEIVE' THEN '请开展偏差调查' WHEN 'DEVIATION_CORRECT' THEN '请完成偏差整改' WHEN 'DEVIATION_VERIFY' THEN CASE WHEN EXISTS (SELECT 1 FROM mes_pro_edhr_deviation_handling vh WHERE vh.deviation_id=mes_pro_edhr_work_task.business_scope_id AND vh.tenant_id=mes_pro_edhr_work_task.tenant_id AND vh.deleted=0 AND vh.corrective_owner_id IS NULL) THEN '请验证偏差调查结果' ELSE '请验证偏差整改结果' END WHEN 'DEVIATION_SIGN' THEN '请完成偏差签署' WHEN 'DEVIATION_APPROVE' THEN '请完成偏差质量审核' WHEN 'DEVIATION_CLOSE' THEN '请关闭偏差' WHEN 'RECORD_CHANGE_APPROVE' THEN '请审批记录变更' WHEN 'RECORD_CHANGE_CORRECTION' THEN '请补正记录变更' WHEN 'DOSSIER_COMPLETE' THEN '请补齐放行资料' WHEN 'PQC_RELEASE_CORRECTION' THEN '请补正生产放行资料' ELSE '任务类型未识别，请核实任务数据' END, CHAR(10), CONCAT('生产订单：', CASE WHEN NULLIF(TRIM(mes_pro_edhr_work_task.work_order_code), '') IS NULL THEN '生产订单编号缺失' ELSE TRIM(mes_pro_edhr_work_task.work_order_code) END, '｜批次：', CASE WHEN NULLIF(TRIM(mes_pro_edhr_work_task.batch_code), '') IS NULL THEN CASE WHEN mes_pro_edhr_work_task.task_type IN ('DEVIATION_RECEIVE','DEVIATION_CORRECT','DEVIATION_VERIFY','DEVIATION_SIGN','DEVIATION_APPROVE','DEVIATION_CLOSE') THEN '未关联批次（按生产订单办理）' ELSE '批次编号缺失' END ELSE TRIM(mes_pro_edhr_work_task.batch_code) END, CASE WHEN NULLIF(TRIM(mes_pro_edhr_work_task.process_name), '') IS NOT NULL AND mes_pro_edhr_work_task.task_type IN ('FILL','REVIEW','APPROVE','REWORK','DOSSIER_COMPLETE') THEN CONCAT('｜工序/资料：', TRIM(mes_pro_edhr_work_task.process_name)) ELSE '' END, CASE WHEN mes_pro_edhr_work_task.task_type IN ('DEVIATION_RECEIVE','DEVIATION_CORRECT','DEVIATION_VERIFY','DEVIATION_SIGN','DEVIATION_APPROVE','DEVIATION_CLOSE') THEN CONCAT('｜办理要求：', CASE WHEN mes_pro_edhr_work_task.task_type IN ('DEVIATION_RECEIVE','DEVIATION_CORRECT') THEN CASE WHEN NULLIF(TRIM(mes_pro_edhr_work_task.reason), '') IS NULL THEN '任务办理要求缺失，请核对偏差记录' ELSE TRIM(mes_pro_edhr_work_task.reason) END ELSE CASE mes_pro_edhr_work_task.signature_cell_key WHEN 'PREPARER' THEN '完成偏差处理记录编制' WHEN 'VERIFIER' THEN '完成纠正措施核验' WHEN 'CORRECTIVE_VERIFIER' THEN '核对调查处理及相关证据并提交验证意见' WHEN 'DEPARTMENT_OWNER' THEN '完成部门负责人确认' WHEN 'QA' THEN '完成 QA 关闭确认' WHEN 'QUALITY_OWNER' THEN '完成质量负责人批准' WHEN 'MANAGEMENT_REP' THEN '完成管理者代表批准' WHEN 'CLOSE' THEN '完成偏差正式关闭' ELSE '偏差职责缺失，请联系管理员' END END) ELSE '' END)) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail, CASE WHEN EXISTS (SELECT 1 FROM mes_pro_edhr_batch_execution frozen WHERE frozen.id=mes_pro_edhr_work_task.batch_execution_id AND frozen.tenant_id=mes_pro_edhr_work_task.tenant_id AND frozen.deleted=0 AND frozen.status=15) AND mes_pro_edhr_work_task.task_type IN ('FILL','REVIEW','APPROVE','REWORK','ARCHIVE','CLOSE') THEN '批次冻结，暂不可处理' ELSE CASE mes_pro_edhr_work_task.status WHEN 'TODO' THEN '待处理' WHEN 'OVERDUE' THEN '已逾期' END END AS status_label, mes_pro_edhr_work_task.create_time AS created_at, COALESCE(mes_pro_edhr_work_task.due_time,mes_pro_edhr_work_task.overdue_at) AS due_at, CONVERT(mes_pro_edhr_work_task.task_type USING utf8mb4) COLLATE utf8mb4_unicode_ci AS domain_task_type, CONVERT(mes_pro_edhr_work_task.action_url USING utf8mb4) COLLATE utf8mb4_unicode_ci AS action_url, CAST(mes_pro_edhr_work_task.batch_execution_id AS CHAR) AS batch_execution_id, CAST(mes_pro_edhr_work_task.batch_task_id AS CHAR) AS batch_task_id, CAST(mes_pro_edhr_work_task.execution_id AS CHAR) AS execution_id, mes_pro_edhr_work_task.business_scope_type, CAST(mes_pro_edhr_work_task.business_scope_id AS CHAR) AS business_scope_id, mes_pro_edhr_work_task.signature_cell_key
FROM mes_pro_edhr_work_task
WHERE mes_pro_edhr_work_task.tenant_id = #{q.tenantId} AND mes_pro_edhr_work_task.deleted = 0 AND mes_pro_edhr_work_task.status IN ('TODO','OVERDUE')
AND mes_pro_edhr_work_task.task_type ${deviationPredicate} ('DEVIATION_RECEIVE','DEVIATION_CORRECT','DEVIATION_VERIFY','DEVIATION_SIGN','DEVIATION_APPROVE','DEVIATION_CLOSE')
AND ${pqcReleaseSql}
AND ${correctionSql}
AND ${dossierSql}
AND ${ownerSql} AND ${lockedSourceSql} AND ${batchSql}
